// Parsear respuesta JSON del LLM
const items = $input.all();
const results = [];

for (const item of items) {
  let extracted = {};

  try {
    let content = item.json.message?.content || item.json.text || '';
    content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    extracted = JSON.parse(content);
    extracted.parse_failed = false;
  } catch (e) {
    extracted = {
      parse_failed: true,
      raw_content: (item.json.message?.content || item.json.text || '').substring(0, 500),
      error: e.message
    };
  }

  if (!extracted.parse_failed && (!extracted.id_transaccion || extracted.id_transaccion === '')) {
    extracted.id_transaccion = Date.now().toString();
  }

  results.push({ json: extracted });
}

return results;

