const items = $input.all();
const chatId = $('📱 Telegram Trigger').item.json.message.chat.id;

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (!items.length || !items[0].json.id_transaccion) {
  return [{ 
    json: { 
      message: '✅ No hay facturas pendientes de comprobante de pago.', 
      ids_json: '[]', 
      has_items: false, 
      chat_id: chatId 
    } 
  }];
}

let msg = '🧾 <b>Adjuntar Comprobante de Pago</b>\n\n';
msg += '📋 <b>Facturas disponibles:</b>\n\n';
const ids = [];

items.forEach((item, i) => {
  const d = item.json;
  ids.push(d.id_transaccion);
  const comercio = esc(d.servicio_comercio) || 'Sin descripción';
  const concepto = esc(d.concepto) || '-';
  const importe = d.importe || '-';
  const fecha = d.fecha_fc || '-';
  const formaPago = esc(d.forma_de_pago) || 'Sin medio de pago';

  msg += `${i + 1}. <b>${comercio}</b>\n`;
  msg += `   ${concepto}\n`;
  msg += `   💰 $${importe} | 📅 ${fecha}\n`;
  msg += `   💳 ${formaPago}\n`;
  msg += `   🏷️ ID: <code>${d.id_transaccion}</code>\n\n`;
});

msg += '---\n';
msg += '✏️ <b>Instrucciones:</b>\n';
msg += '1️⃣ Escribi el <b>número</b> de la factura\n';
msg += '2️⃣ Adjuntá el <b>comprobante de pago</b> (foto o PDF)\n\n';
msg += '<b>Ejemplo:</b> Escribi <code>3</code> y luego enviá la foto del comprobante\n\n';
msg += '❌ Escribi <b>cancelar</b> para salir';

return [{ json: { message: msg, ids_json: JSON.stringify(ids), has_items: true, chat_id: chatId } }];

const message = $('📱 Telegram Trigger').item.json.message;
const sesionData = $('🔎 Verificar Sesion').first().json;
const chatId = message.chat.id;
const userName = `${message.from.first_name} ${message.from.last_name || ''}`.trim();

if (message.text && message.text.toLowerCase().trim() === 'cancelar') {
  return [{ json: { action: 'cancelar', chat_id: chatId, message: '❌ Operación cancelada.' } }];
}

const allIds = sesionData.facturas_pendientes || [];
const selectedId = sesionData.facturas_seleccionadas;

if (message.photo || message.document) {
  if (!selectedId) {
    return [{ json: { action: 'error', chat_id: chatId, message: '⚠️ Primero escribí el número de la factura, luego enviá el comprobante.' } }];
  }
  let fileId = null;
  let fileName = null;
  let mimeType = null;
  let isPhoto = false;
  if (message.photo && message.photo.length > 0) {
    fileId = message.photo[message.photo.length - 1].file_id;
    fileName = `comprobante_${Date.now()}.jpg`;
    mimeType = 'image/jpeg';
    isPhoto = true;
  } else if (message.document) {
    fileId = message.document.file_id;
    fileName = message.document.file_name || `comprobante_${Date.now()}.pdf`;
    mimeType = message.document.mime_type;
  }
  return [{ json: { action: 'procesar_archivo', chat_id: chatId, file_id: fileId, file_name: fileName, mime_type: mimeType, id_transaccion: selectedId, is_photo: isPhoto } }];
}

if (message.text) {
  const num = parseInt(message.text.trim());
  if (isNaN(num) || num < 1 || num > allIds.length) {
    return [{ json: { action: 'error', chat_id: chatId, message: `⚠️ Número inválido. Elegí entre 1 y ${allIds.length}, o enviá cancelar.` } }];
  }
  return [{ json: { action: 'esperar_archivo', chat_id: chatId, selected_id: allIds[num - 1], selected_index: num, message: `✅ Seleccionaste la factura *${num}*.

📎 Ahora enviá el comprobante de pago (foto o PDF).` } }];
}

return [{ json: { action: 'error', chat_id: chatId, message: '⚠️ Formato no reconocido. Escribí el número de la factura o enviá cancelar.' } }];

const idTransaccion = $('Procesar Respuesta Comp1').item.json.id_transaccion;
const driveLink = $('Subir Comprobante Drive1').first().json.webViewLink || '';
const fechaPago = new Date().toLocaleDateString('es-AR');

return [{ 
  json: { 
    'ID DE TRANSACCION': idTransaccion,
    'ESTADO': 'Pagado',
    'Fecha de ingreso de pago': fechaPago,
    'link comprobante': driveLink,
    'Envio comprobante s/n': 'Si'
  } 
}];

